class Solution {
    public List<Integer> findLonely(int[] nums){
        Map<Integer,Integer> count=new HashMap<>();
        for(int value:nums)count.merge(value,1,Integer::sum);
        List<Integer> answer=new ArrayList<>();
        for(int value:nums)if(count.get(value)==1&&!count.containsKey(value-1)&&!count.containsKey(value+1))answer.add(value);
        return answer;
    }
}

code.kotlin:
class Solution {
    fun findLonely(nums:IntArray):List<Int>{
        val count=nums.toList().groupingBy{
            it
        }.eachCount();
        return nums.filter{
            count[it]==1&&!count.containsKey(it-1)&&!count.containsKey(it+1)
        }
    }
}

